<script setup lang="ts">import { useDrawerContext } from './context'; const { drawer, snapshot, triggerElement } = useDrawerContext('DrawerTrigger'); function triggerProps() { return { type: 'button' as const, 'aria-haspopup': 'dialog' as const, 'aria-expanded': snapshot.value.open, 'data-state': snapshot.value.open ? 'open' : 'closed', onClick: (event: MouseEvent) => drawer.toggle({ source: 'trigger', event }) } } function setRef(element: HTMLButtonElement | null) { triggerElement.value = element }</script>
<template><slot :props="triggerProps()" :ref="setRef" :state="snapshot" /></template>
